def find(sizes, m=44, timeout=20000, seed=0):
    n=sum(sizes)
    colors=[]
    for c,s in enumerate(sizes): colors += [c]*s
    pairs=[]; var={}
    for i in range(n):
        for j in range(i+1,n):
            if colors[i]!=colors[j]:
                var[(i,j)] = Bool(f'e_{i}_{j}')
                pairs.append((i,j))
    def E(i,j):
        if i>j: i,j=j,i
        if i==j or colors[i]==colors[j]: return False
        return var[(i,j)]
    s=Solver()
    s.set(timeout=timeout, random_seed=seed)
    # no triangles
    tri=0
    for a,b,c in combinations(range(n),3):
        es=[E(a,b),E(a,c),E(b,c)]
        if all(e is not False for e in es):
            s.add(Or(Not(es[0]),Not(es[1]),Not(es[2]))); tri+=1
    # no C4: for ordered cycles on 4-set: (a,b,c,d),(a,b,d,c),(a,c,b,d)
    c4=0
    for a,b,c,d in combinations(range(n),4):
        cycles=[(a,b,c,d),(a,b,d,c),(a,c,b,d)]
        for cyc in cycles:
            es=[E(cyc[0],cyc[1]), E(cyc[1],cyc[2]), E(cyc[2],cyc[3]), E(cyc[3],cyc[0])]
            if all(e is not False for e in es):
                s.add(Or(*[Not(e) for e in es])); c4+=1
    s.add(PbGe([(var[p],1) for p in pairs], m))
    print('sizes',sizes,'vars',len(pairs),'tri',tri,'c4',c4,'constraints',len(s.assertions()))
    res=s.check()
    print('res',res)
    if res==sat:
        mo=s.model()
        edges=[p for p in pairs if is_true(mo.eval(var[p], model_completion=True))]
        print('edges',len(edges))
        return colors,edges
    return None,None

