from itertools import combinations
from pysat.solvers import Cadical153, Glucose3, Minisat22
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

def solve(sizes, m=44, time_limit=None):
    n=sum(sizes)
    colors=[]
    for c,s in enumerate(sizes): colors += [c]*s
    vpool=IDPool()
    var={}
    lits=[]
    for i in range(n):
        for j in range(i+1,n):
            if colors[i]!=colors[j]:
                var[(i,j)]=vpool.id((i,j)); lits.append(var[(i,j)])
    def E(i,j):
        if i>j: i,j=j,i
        if colors[i]==colors[j]: return None
        return var[(i,j)]
    clauses=[]
    for a,b,c in combinations(range(n),3):
        es=[E(a,b),E(a,c),E(b,c)]
        if all(x is not None for x in es): clauses.append([-es[0],-es[1],-es[2]])
    for a,b,c,d in combinations(range(n),4):
        for cyc in [(a,b,c,d),(a,b,d,c),(a,c,b,d)]:
            es=[E(cyc[0],cyc[1]), E(cyc[1],cyc[2]), E(cyc[2],cyc[3]), E(cyc[3],cyc[0])]
            if all(x is not None for x in es): clauses.append([-x for x in es])
    card=CardEnc.atleast(lits=lits, bound=m, vpool=vpool, encoding=EncType.totalizer)
    clauses += card.clauses
    print('sizes',sizes,'vars',len(lits),'clauses',len(clauses),'top',vpool.top)
    with Cadical153(bootstrap_with=clauses) as solver:
        sat=solver.solve()
        print('sat',sat)
        if sat:
            model=set(x for x in solver.get_model() if x>0)
            edges=[p for p,vid in var.items() if vid in model]
            print('edges',len(edges))
            return edges,colors
    return None,None

for sizes in [(8,8,7),(9,7,7),(9,8,6),(10,7,6),(10,8,5),(11,6,6),(12,6,5),(13,5,5)]:
    edges,colors=solve(sizes)
    if edges:
        print('FOUND',sizes)
        print(edges)
        break

